SELECT city, rating_bucket, singapore_count FROM (SELECT city, CASE WHEN rating >= 3.7 THEN 'high' WHEN rating >= 1.7 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(CASE WHEN city = 'Singapore' THEN 1 END) AS singapore_count FROM suppliers WHERE country = 'US' GROUP BY city, CASE WHEN rating >= 3.7 THEN 'high' WHEN rating >= 1.7 THEN 'mid' ELSE 'low' END) AS sub WHERE singapore_count >= 9;
